 11	// ---------------------------------------------------------------------------
 12	// Route registration
 13	// ---------------------------------------------------------------------------
 14	
 15	/**
 16	 * Registers all routes for the `/api/repositories` resource group on the
 17	 * provided `Router` instance. This includes five standard CRUD routes and two
 18	 * credential-management routes that require access to the application
 19	 * configuration.
 20	 *
 21	 * All handlers delegate to the supplied `RepositoryManager` and map results
 22	 * or errors to the appropriate HTTP status codes:
 23	 *
 24	 * | Method | Path                                        | Success | Failure |
 25	 * |--------|---------------------------------------------|---------|---------|
 26	 * | GET    | /api/repositories                           | 200     | —       |
 27	 * | GET    | /api/repositories/:id                       | 200     | 404     |
 28	 * | POST   | /api/repositories                           | 201     | 400     |
 29	 * | PUT    | /api/repositories/:id                       | 200     | 404     |
 30	 * | DELETE | /api/repositories/:id                       | 204     | 404     |
 31	 * | POST   | /api/repositories/:id/refresh-timestamp     | 200     | 404     |
 32	 * | PUT    | /api/repositories/:id/credential            | 200     | 400/404 |
 33	 * | GET    | /api/repositories/:id/credential-options    | 200     | 404     |
 34	 */
 35	export function registerRepositoryRoutes(
 36	    router: Router,
 37	    repoManager: RepositoryManager,
 38	    appConfig: AppConfig,
 39	    errorLogManager?: ErrorLogManager,
 40	): void {
 41	    /**
 42	     * Look up a repository by ID.
 43	     *
 44	     * Sends a `404` response and returns `undefined` when the repository
 45	     * cannot be found.
 46	     *
 47	     * @param res          - The outgoing HTTP response (used to send the 404 error).
 48	     * @param repositoryId - The ID of the repository to look up.
 49	     * @returns The matching `Repository` on success, or `undefined` when a 404
 50	     *          has already been written to `res`.
 51	     */
 52	    function resolveRepository(
 53	        res: ServerResponse,
 54	        repositoryId: string,
 55	    ): Repository | undefined {
 56	        const repo = repoManager.getById(repositoryId);
 57	        if (repo === undefined) {
 58	            sendError(res, 404, `Repository with ID "${repositoryId}" not found.`);
 59	            return undefined;
 60	        }
 61	        return repo;
 62	    }
 63	
 64	    // ------------------------------------------------------------------
 65	    // GET /api/repositories — list all
 66	    // ------------------------------------------------------------------
 67	    router.get('/api/repositories', (
 68	        _req: IncomingMessage,
 69	        res: ServerResponse,
 70	        _params: Record<string, string>,
 71	    ): void => {
 72	        const repos = repoManager.list();
 73	        sendJson(res, 200, repos);
 74	    });
 75	
 76	    // ------------------------------------------------------------------
 77	    // GET /api/repositories/:id — get one
 78	    // ------------------------------------------------------------------
 79	    router.get('/api/repositories/:id', (
 80	        _req: IncomingMessage,
 81	        res: ServerResponse,
 82	        params: Record<string, string>,
 83	    ): void => {
 84	        const repo = resolveRepository(res, params['id']);
 85	        if (repo === undefined) return;
 86	        sendJson(res, 200, repo);
 87	    });
 88	
 89	    // ------------------------------------------------------------------
 90	    // POST /api/repositories — create
 91	    // ------------------------------------------------------------------
 92	    router.post('/api/repositories', async (
 93	        req: IncomingMessage,
 94	        res: ServerResponse,
 95	        _params: Record<string, string>,
 96	    ): Promise<void> => {
 97	        let body: unknown;
 98	        try {
 99	            body = await parseJsonBody(req);
100	        } catch (err) {

101	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
102	            return;
103	        }
104	
105	        if (!isPlainObject(body)) {
106	            sendError(res, 400, 'Request body must be a JSON object.');
107	            return;
108	        }
109	
110	        const { url, name, id } = body as {
111	            url?: unknown;
112	            name?: unknown;
113	            id?: unknown;
