115	
116	        if (typeof url !== 'string' || url.trim() === '') {
117	            sendError(res, 400, 'Missing required field: url (non-empty string).');
118	            return;
119	        }
120	
121	        const params: { url: string; name?: string; id?: string } = { url: url.trim() };
122	        if (typeof name === 'string') params.name = name;
123	        if (typeof id === 'string') params.id = id;
124	
125	        try {
126	            const repo = repoManager.add(params);
127	            sendJson(res, 201, repo);
128	        } catch (err) {
129	            sendError(res, 400, err instanceof Error ? err.message : 'Could not create repository.');
130	        }
131	    });
