133	    // ------------------------------------------------------------------
134	    // PUT /api/repositories/:id — update
135	    // ------------------------------------------------------------------
136	    router.put('/api/repositories/:id', async (
137	        req: IncomingMessage,
138	        res: ServerResponse,
139	        params: Record<string, string>,
140	    ): Promise<void> => {
141	        const id = params['id'];
142	
143	        if (!repoManager.exists(id)) {
144	            sendError(res, 404, `Repository with ID "${id}" not found.`);
145	            return;
146	        }
147	
148	        let body: unknown;
