150	            body = await parseJsonBody(req);
151	        } catch (err) {
152	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
153	            return;
154	        }
155	
156	        if (!isPlainObject(body)) {
157	            sendError(res, 400, 'Request body must be a JSON object.');
158	            return;
159	        }
