168	        try {
169	            const updated = repoManager.update(id, { name: name.trim() });
170	            sendJson(res, 200, updated);
171	        } catch (err) {
172	            // update() throws NotFoundError if the ID was removed
173	            // between the exists() check and the update() call (race condition).
174	            if (err instanceof NotFoundError) {
175	                sendError(res, 404, err.message);
176	            } else {
177	                sendError(res, 500, 'Internal server error.');
178	            }
179	        }
180	    });
