185	    router.delete('/api/repositories/:id', (
186	        _req: IncomingMessage,
187	        res: ServerResponse,
188	        params: Record<string, string>,
189	    ): void => {
190	        const id = params['id'];
191	
192	        try {
193	            repoManager.remove(id);
