232	    // ------------------------------------------------------------------
233	    // PUT /api/repositories/:id/credential — set or clear credential
234	    //
235	    //   Accepts `{ credentialId: string | null }`.
236	    //   - When `credentialId` is a non-empty string, validates that it
237	    //     references an existing entry in `appConfig.gitCredentials`, then
238	    //     calls `RepositoryManager.updateCredential()` to persist the
239	    //     association.
240	    //   - When `credentialId` is `null`, clears the association.
241	    //   Returns the updated `Repository` on success (200).
242	    // ------------------------------------------------------------------
243	    router.put('/api/repositories/:id/credential', async (
244	        req: IncomingMessage,
245	        res: ServerResponse,
246	        params: Record<string, string>,
247	    ): Promise<void> => {
248	        const id = params['id'];
249	
250	        const repo = resolveRepository(res, id);
251	        if (repo === undefined) return;
252	
253	        let body: unknown;
254	        try {
255	            body = await parseJsonBody(req);
256	        } catch (err) {
257	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
258	            return;
259	        }
260	
261	        if (!isPlainObject(body)) {
262	            sendError(res, 400, 'Request body must be a JSON object.');
263	            return;
264	        }
265	
266	        const { credentialId } = body as { credentialId?: unknown };
267	
268	        if (credentialId !== null && typeof credentialId !== 'string') {
269	            sendError(res, 400, 'Missing required field: credentialId (string or null).');
270	            return;
271	        }
272	
273	        if (typeof credentialId === 'string') {
274	            // Validate that the referenced credential exists in the config.
275	            const credentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
276	            const exists = credentials.some((c) => c.id === credentialId);
277	            if (!exists) {
278	                sendError(
279	                    res,
280	                    400,
281	                    `Credential with ID "${credentialId}" does not exist in the application configuration.`,
282	                );
283	                return;
284	            }
285	        }
286	
287	        try {
288	            const updated = repoManager.updateCredential(id, credentialId as string | null);
289	
290	            // Audit log — emit assign or clear event.
291	            const auditOperation = credentialId === null ? 'clear-credential' : 'assign-credential';
292	            errorLogManager?.append({
